            address(uniswapV3Factory), address(1), address(new MockTokenDescriptorRe_Dec())
        );
    }

    function _uH(uint256 human) internal view returns (uint256) {
        return _uToken(address(hostile), human);
    }

    function _uP(uint256 human) internal view returns (uint256) {
        return _uToken(address(pairToken), human);
    }

    function _seedHostilePool() internal {
        int24 spacing = hostilePool.tickSpacing();
        int24 tickLower = (-887220 / spacing) * spacing;
        int24 tickUpper = (887220 / spacing) * spacing;
        if (tickLower >= tickUpper) {
            tickLower = -spacing * 1000;
            tickUpper = spacing * 1000;
        }
        uint8 d0 = IERC20Metadata(hostilePool.token0()).decimals();
        uint8 d1 = IERC20Metadata(hostilePool.token1()).decimals();
        hostile.mint(address(this), 100_000_000 * (10 ** uint256(_tokenADecimals())));
        pairToken.mint(address(this), 100_000_000 * (10 ** uint256(_tokenBDecimals())));
        uint256 geom = 10 ** (uint256(d0 + d1) / 2);
        uint128 liq = uint128(50_000_000 * geom);
