        );
    }

    /// @notice H2: failed exchangeOut (maxIn too low) is atomic — attacker inventory unchanged.
    function test_H2_exchangeOut_maxInTooLow_balancesUnchanged() public {
        uint256 amountOut_ = 0.1 ether;
        address token0_ = _token0();
