        assertLt(minted, supply);
        assertLe(minted * (1_000_000 + (token1_ ? 0 : donated)), 1_000_000 * supply);
        assertLe(minted * (10_000_000 + (token1_ ? donated : 0)), 10_000_000 * supply);
